const MuteToggleButton: React.FC<IBaseRoomProps> = ({
    member,
    room,
    powerLevels,
    startUpdating,
    stopUpdating,
    isAdminActionPending,
    tryStartAdminAction,
    finishAdminAction,
}) => {
    const cli = useContext(MatrixClientContext);
    const actionLock = useAdminActionLock(member, { isAdminActionPending, tryStartAdminAction, finishAdminAction });

    // Don't show the mute/unmute option if the user is not in the room
    if (member.membership !== "join") return null;

    const muted = isMuted(member, powerLevels);
    const onMuteToggle = async (): Promise<void> => {
        if (!actionLock.begin()) return;

        let updating = false;
        try {
            const roomId = member.roomId;
            const target = member.userId;

            // if muting self, warn as it may be irreversible
            if (target === cli.getUserId()) {
                try {
                    if (!(await warnSelfDemote(room?.isSpaceRoom()))) return;
                } catch (e) {
                    logger.error("Failed to warn about self demotion: ", e);
                    throw e;
                }
            }

            const powerLevelEvent = room.currentState.getStateEvents("m.room.power_levels", "");
            if (!powerLevelEvent) return;

            const powerLevels = powerLevelEvent.getContent();
            const levelToSend =
                (powerLevels.events ? powerLevels.events["m.room.message"] : null) || powerLevels.events_default;
            let level;
            if (muted) {
                // unmute
                level = levelToSend;
            } else {
                // mute
                level = levelToSend - 1;
            }
            level = parseInt(level);

            if (!isNaN(level)) {
                startUpdating();
                updating = true;
                await cli.setPowerLevel(roomId, target, level, powerLevelEvent);
                // NO-OP; rely on the m.room.member event coming down else we could
                // get out of sync if we force setState here!
                logger.log("Mute toggle success");
            }
        } catch (err) {
            logger.error("Mute error: " + err);
            Modal.createDialog(ErrorDialog, {
                title: _t("Error"),
                description: _t("Failed to mute user"),
            });
        } finally {
            if (updating) stopUpdating();
            actionLock.finish();
        }
    };

    const classes = classNames("mx_UserInfo_field", {
        mx_UserInfo_destructive: !muted,
    });

    const muteLabel = muted ? _t("Unmute") : _t("Mute");
    return (
        <AccessibleButton kind="link" className={classes} disabled={actionLock.pending} onClick={onMuteToggle}>
            {muteLabel}
        </AccessibleButton>
    );
};

